insert into quiz_domain_lessons (domain, title, content, key_terms) values
  ('ib_eng_markets', '주문의 길: FIX에서 체결까지', 'IB 테크의 첫 층은 화면이 아니라 세션이다. OMS는 주문의 생애(접수·라우팅·상태)를 소유하고, EMS는 어디로 보낼지(스마트 오더 라우팅, 알고리즘)를 고른다. 둘을 한 프로세스에 넣으면 책임이 섞여 장애 때 어느 장부가 맞는지 모른다. 와이어는 대개 FIX다. MsgType(35)이 메시지 종류이고, ClOrdID(11)는 우리 쪽 주문 키, ExecID(17)는 체결 키다. 같은 체결을 두 번 적용하면 포지션이 틀린다. 주문 유형(Limit/Market/IOC/FOK)과 TIF는 매칭 엔진의 규칙이지 UI 라벨이 아니다. 시세는 스냅샷과 증분이 다르고, 시퀀스 갭을 무시하면 호가가 조용히 틀린다.', array['FIX', 'MsgType(35)', 'ClOrdID', 'ExecID', 'OrdStatus', 'OMS', 'EMS', 'IOC', 'FOK', 'drop copy', 'price-time', 'gap fill']),
  ('ib_eng_latency', '평균이 아니라 꼬리가 상품이다', '마켓즈에서 느린 한 건이 기회를 죽인다. 평균 지연이 아니라 p99/p999와 jitter를 본다. 핫패스에서 힙 할당을 하면 GC가 예측 못 하는 정지를 만든다. 캐시 라인(보통 64B)을 두 스레드가 쓰면 false sharing으로 혼자 쓸 때보다 느려진다. 대기열에서 park하면 깨어나는 비용이 생기고, 바쁜 루프는 CPU를 태운다. 시계는 NTP로 맞춘 wall clock과 TSC 기반 단조 시계를 섞어 쓰면 구간 측정이 거짓말이 된다. 시스템콜·로그·예외를 핫패스에 두면 벤치마크와 장이 갈린다.', array['tail latency', 'p99', 'GC pause', 'false sharing', 'cache line', 'busy-spin', 'TSC', 'kernel bypass', 'allocation', 'jitter', 'huge pages', 'mechanical sympathy']),
  ('ib_eng_concurrency', '잠금보다 소유권을 먼저 나눈다', '체결 스레드가 같은 호가창을 잠그고 기다리면 지연이 잠금 시간이 된다. Java Memory Model에서 한 스레드의 쓰기가 다른 스레드에 보이려면 happens-before가 필요하다. volatile은 가시성과 단일 변수의 원자성이지 복합 불변식의 보호가 아니다. CAS는 락 없이 갱신하지만 ABA에 속는다. 거래 경로에서 자주 쓰는 답은 단일 작성자(single-writer)다. 큐에 넣고 한 스레드만 장부를 바꾼다. Disruptor 같은 링 버퍼는 그 패턴의 구현이다. 공유 가변 상태를 줄이는 쪽이 synchronized를 잘 쓰는 쪽보다 면접에서 더 깊게 보인다.', array['happens-before', 'volatile', 'synchronized', 'CAS', 'ABA', 'single-writer', 'Disruptor', 'deadlock', 'livelock', 'publication', 'immutable', 'false sharing']),
  ('ib_eng_data', '체결은 사건이고 포지션은 합이다', '주문·체결·포지션을 한 행에 덮어쓰면 대사가 불가능하다. ExecID unique로 체결을 한 번만 넣고, 포지션은 부호 있는 수량의 합이다. 같은 체결이 드롭카피로 두 번 오면 insert가 거절되어야 한다. 격리 수준을 낮추면 아직 확정되지 않은 체결을 리스크가 읽고, 높이면 장이 기다린다. VWAP은 가격×수량 합 / 수량 합이고 창함수로 구간을 자른다. EOD 스냅샷은 as-of다. 시계가 두 개면 같은 사건이 다른 날에 들어간다. 대사는 우리 장부와 거래소·브로커 장부의 차이다. 차이를 수동으로 고치면 다음 날 또 틀린다.', array['ExecID', 'idempotent insert', 'READ COMMITTED', 'SERIALIZABLE', 'lost update', 'VWAP', 'window function', 'as-of', 'reconcile', 'drop copy', 'signed quantity', 'event log']),
  ('ib_eng_systems', '막아야 할 때 전체가 서야 한다', '거래 시스템은 처리량보다 잘못 체결하지 않는 쪽이 먼저다. kill switch는 신규 주문을 멈추고, 이미 나간 주문을 어떻게 할지는 별 규칙이다. 네트워크는 at-least-once가 기본이다. exactly-once는 전송 마법이 아니라 수신 쪽 멱등(ExecID, 시퀀스)이다. 저널에 쓰고 재생할 수 있어야 프로세스가 죽어도 장부가 맞다. 주문 테이블과 체결 테이블을 따로 커밋하면 한쪽만 남는 이중 쓰기가 난다. 리스크는 전송 전 검사와 전송 후 검사가 다르고, 한도 경쟁은 한 스레드나 원자적 예약으로 막는다. 대사가 소스 오브 트루스다.', array['kill switch', 'at-least-once', 'idempotent consumer', 'journal', 'replay', 'dual write', 'backpressure', 'pre-trade risk', 'post-trade risk', 'poison message', 'sequence gap', 'warm standby']),
  ('ib_eng_ds', '호가창은 정렬된 두 쪽이다', '매수는 높은 가격이 앞이고 매도는 낮은 가격이 앞이다. 같은 가격은 먼저 들어온 수량이 먼저 나간다(price-time). 구현은 가격 레벨을 트리/힙으로, 레벨 안은 큐로 두는 식이 흔하다. VWAP은 구간 합이지 종가의 평균이 아니다. 중앙값 마크는 두 힙(낮은 쪽 max-heap, 높은 쪽 min-heap)으로 스트리밍할 수 있다. 슬라이딩 윈도우 거래량은 deque로 만료를 뺀다. 중복 체결은 ExecID 집합이다. 스탑 주문을 감시하는 쪽은 트리거 가격 우선순위 큐다. 면접에서 일반 두 합(two-sum)을 내기보다 이 장부 이야기로 자료구조를 설명하면 IB 맥락이 맞다.', array['order book', 'price-time priority', 'bid/ask', 'VWAP', 'two heaps', 'sliding window', 'deque', 'hash set', 'priority queue', 'binary search', 'prefix sum', 'FIFO level']);
insert into quiz_questions (domain, module_slug, concept_hint, question, choices, answer_index, explanation, difficulty) values
  ('ib_eng_markets', 'ib_eng/fix-msgtype', '와이어에서 메시지 종류와 주문 식별자는 다른 태그다.', 'FIX에서 이 메시지가 새 주문인지 체결 보고인지 먼저 가르는 태그는?', array['35 MsgType', '11 ClOrdID', '55 Symbol', '49 SenderCompID'], 0, '35가 메시지 종류다. D는 New Order Single, 8은 Execution Report. ClOrdID는 우리 주문 키이고 종류를 말하지 않는다.', 1),
  ('ib_eng_markets', 'ib_eng/clordid-vs-execid', '주문 키와 체결 키를 섞으면 부분 체결을 중복하거나 놓친다.', '같은 주문의 부분 체결이 두 번 들어왔다. 포지션에 수량을 한 번만 더하려면 무엇을 unique 키로 써야 하는가?', array['ClOrdID(11)', 'ExecID(17)', 'OrderID(37) + 심볼', 'SenderCompID + 시각'], 1, 'ClOrdID는 주문 전체의 키라 부분 체결이 여러 개다. 각 체결의 키는 ExecID다. OrderID는 거래소 주문 키이지 체결 키가 아니다.', 2),
  ('ib_eng_markets', 'ib_eng/oms-vs-ems', '장부 소유권과 집행 결정은 다른 실패 모드를 만든다.', 'OMS와 EMS를 나누는 가장 정확한 이유는?', array['OMS는 GUI, EMS는 서버', 'OMS는 주문 생애와 상태, EMS는 라우팅·집행', 'OMS는 주식, EMS는 파생', '둘은 같은 말이다'], 1, 'OMS는 접수·승인·상태·컴플라이언스 장부다. EMS는 어디 보낼지와 알고리즘 집행이다. GUI 여부로 나누면 책임이 안 보인다.', 2),
  ('ib_eng_markets', 'ib_eng/tif-ioc', 'IOC와 FOK는 잔량을 남기는지에서 갈린다.', 'IOC(Immediate or Cancel)의 의미는?', array['지금 체결되지 않은 잔량은 즉시 취소', '전량 체결되지 않으면 주문 전체를 거절', '장 끝날 때까지 남긴다', '지정가에 닿을 때까지 대기'], 0, 'IOC는 즉시 가능한 수량만 체결하고 잔량은 취소한다. 전량 아니면 전부 거절은 FOK다. Day/GTC는 잔량을 남긴다.', 1),
  ('ib_eng_markets', 'ib_eng/tif-fok', '부분 체결이 리스크를 깨는 주문이 있다.', 'FOK(Fill or Kill)를 쓰는 이유는?', array['부분 체결을 허용하려고', '전량이 지금 안 되면 아무 체결도 남기지 않으려고', '다음날까지 주문을 유지하려고', '호가 중간 가격에 대기하려고'], 1, 'FOK는 전량 즉시 체결이 아니면 전체를 죽인다. 부분 포지션이 생기면 안 되는 헤지·스프레드에 쓴다.', 1),
  ('ib_eng_markets', 'ib_eng/limit-vs-market', '가격 우선과 즉시성 우선을 구분한다.', '지정가(Limit)와 시장가(Market)의 차이는?', array['지정가는 수량만, 시장가는 가격만 정한다', '지정가는 가격 한도, 시장가는 지금 가능한 호가에 체결', '지정가는 장전만, 시장가는 정규장만', '둘 다 가격을 보장한다'], 1, '지정가는 그 가격 이상으로 불리해지지 않는다. 시장가는 속도가 우선이고 체결가는 호가에 달렸다. 시장가가 가격을 보장하지 않는다.', 1),
  ('ib_eng_markets', 'ib_eng/price-time', '가격이 같으면 시간의 큐다.', '가격-시간 우선(price-time) 호가창에서 같은 가격의 두 매수 중 먼저 체결되는 쪽은?', array['수량이 더 큰 주문', '먼저 들어온 주문', '나중에 들어온 주문', '고객 주문이 자기 계정 주문보다 항상 앞'], 1, '같은 가격에서는 먼저 표시된 수량이 먼저 나간다(FIFO). 수량이 크다고 새치기하지 않는다. 프로 라타 매칭은 다른 규칙이다.', 2),
  ('ib_eng_markets', 'ib_eng/ordstatus-vs-exectype', '사건과 현재 상태는 같은 태그가 아니다.', 'Execution Report에서 OrdStatus와 ExecType을 섞어 읽으면 생기는 전형적인 버그는?', array['심볼을 잘못 파싱한다', '부분 체결 이후에도 New로 보이거나, 상태와 이벤트를 덮어쓴다', 'ClOrdID가 길면 잘린다', '시세 스냅샷이 비어 있다'], 1, 'ExecType은 이번 메시지의 사건(부분 체결, 취소됨)이고 OrdStatus는 주문의 현재 상태다. 사건으로 상태를 덮거나 반대로 읽으면 장부가 과거로 돌아간다.', 3),
  ('ib_eng_markets', 'ib_eng/drop-copy', '주문 경로와 관찰 경로를 나눈다.', '드롭카피(drop copy) 세션이 있는 이유는?', array['시세를 더 싸게 받기 위해', '주문 세션과 분리해 체결·상태를 감시·리스크·대사로 보내기 위해', '주문을 두 거래소에 동시에 내기 위해', 'FIX 대신 REST를 쓰기 위해'], 1, '주문 세션이 죽어도 드롭카피로 체결을 받을 수 있다. 리스크·미들오피스가 주문 게이트를 공유하지 않게 한다. 시세 피드가 아니다.', 2),
  ('ib_eng_markets', 'ib_eng/md-gap', '시세는 이벤트가 아니라 상태에 대한 차분이다.', '증분 시세에서 시퀀스 번호가 하나 비면 무엇을 해야 하는가?', array['빈 번호를 0 수량으로 채운다', '갭을 메울 스냅샷/재전송을 받기 전까지 그 호가를 신뢰하지 않는다', '마지막 호가를 두 번 적용한다', '무시하고 다음 증분을 더한다'], 1, '증분은 이전 상태에 대한 델타다. 갭을 건너뛰면 호가가 조용히 틀린다. 스냅샷이나 gap fill 뒤에 다시 따라간다.', 2),
  ('ib_eng_markets', 'ib_eng/tplus-settle', '장부와 은행 잔고의 시계가 다르다.', '주식 거래일(T)과 결제(T+1 등)를 포지션 시스템에 섞으면?', array['체결 수량이 항상 0이 된다', '거래 포지션과 결제 포지션의 날짜가 어긋나 리스크/잔고가 틀린다', 'FIX MsgType이 바뀐다', 'IOC가 FOK가 된다'], 1, '체결은 거래일에 포지션을 바꾸고, 현금·증권 이동은 결제일에 일어난다. 한 날짜 필드만 쓰면 어느 쪽이 리스크인지 모른다.', 1),
  ('ib_eng_markets', 'ib_eng/stp-break', '자동 처리의 전제는 양측이 같은 계약을 보고 있는 것이다.', 'STP(Straight-through processing)가 깨져 트레이드 브레이크가 나는 전형적인 원인은?', array['호가창 깊이가 10단 미만', '상대·수량·가격·결제일이 양측 장부에서 다름', 'GC 일시정지가 10ms', 'MsgType이 Heartbeat'], 1, '브레이크는 합의가 안 맞는 체결이다. 필드 하나라도 다르면 자동 정산이 멈춘다. 지연이나 하트비트와는 다른 문제다.', 2),
  ('ib_eng_markets', 'ib_eng/hard-vs-soft-limit', '막을 수 있는 시점과 알리기만 하는 시점이 다르다.', '프리트레이드 한도에서 hard limit과 soft limit의 차이는?', array['hard는 주문을 거절, soft는 경고만 하고 통과시킬 수 있다', 'hard는 주식, soft는 채권', 'hard는 야간, soft는 주간', '둘 다 체결 후에만 검사한다'], 0, 'hard는 전송을 막는다. soft는 사람이 보고 진행할 수 있다. 둘 다 보낸 뒤에만 보면 이미 시장에 나가 있다.', 2),
  ('ib_eng_markets', 'ib_eng/new-order-single', '보내기 전에 우리가 정하는 키가 있다.', 'FIX New Order Single(MsgType D)에 반드시 있어야 하는 식별은?', array['우리 쪽 ClOrdID와 side·수량·심볼', 'ExecID만', '전일 종가', '회계 계정과목'], 0, '새 주문은 클라이언트가 ClOrdID를 붙인다. ExecID는 체결 보고에 온다. 종가나 계정과목은 와이어 주문이 아니다.', 1),
  ('ib_eng_markets', 'ib_eng/session-vs-app', '연결 유지와 업무 사건은 같은 바이트 스트림의 다른 층이다.', 'FIX 세션 메시지(Logon, Heartbeat, Resend)와 애플리케이션 메시지(주문, 체결)를 한 소켓에서 어떻게 다루는가?', array['세션만 TCP, 애플리케이션만 UDP', '같은 세션 시퀀스로 보내되 계층을 나눠 시퀀스 갭과 업무 로직을 섞지 않는다', '하트비트마다 주문을 재전송한다', 'Logon이 오면 전 호가를 지운다'], 1, '한 커넥션에 두 층이 있다. 시퀀스 복구는 세션 층이고, 주문 상태는 애플리케이션 층이다. 하트비트를 주문으로 취급하면 장부가 오염된다.', 2),
  ('ib_eng_latency', 'ib_eng/tail-not-mean', '상품은 평균 속도가 아니라 예측 가능한 꼬리다.', '호가 반응 시간을 평균만 보고 배포하면 놓치는 것은?', array['패킷 크기', '드문 긴 지연(p99)이 체결을 놓치게 함', '심볼 개수', 'FIX 버전'], 1, '평균은 대부분 빠른 건에 가려진다. 장중 한 번의 GC나 락 대기가 그 구간의 기회를 죽인다. p99와 jitter를 본다.', 1),
  ('ib_eng_latency', 'ib_eng/gc-hot-path', '빠른 코드의 적은 보이지 않는 수거다.', '핫패스에서 매 틱마다 새 객체를 만들면 생기는 일은?', array['컴파일이 빨라진다', 'GC 일시정지가 예측 못 하는 지연을 만든다', 'TCP가 자동으로 꺼진다', '호가 시퀀스가 리셋된다'], 1, '할당은 나중에 수거 비용이 된다. 정지형 GC는 모든 스레드를 멈출 수 있다. 핫패스는 미리 할당하거나 오프힙/풀을 쓴다.', 2),
  ('ib_eng_latency', 'ib_eng/false-sharing', '공유하는 것은 변수 이름이 아니라 캐시 라인이다.', '두 스레드가 다른 변수를 쓰는데 성능이 같이 죽는 전형적인 이유는?', array['두 변수가 같은 캐시 라인에 있어 라인을 뺏는다', '변수가 같은 이름이다', '둘 다 volatile이 아니다', 'GC가 꺼져 있다'], 0, '캐시는 라인 단위(보통 64B)로 움직인다. 다른 필드라도 한 라인에 있으면 쓰기마다 상대 캐시가 무효가 된다. 패딩으로 줄을 나눈다.', 2),
  ('ib_eng_latency', 'ib_eng/busy-spin-vs-park', '대기에도 종류가 있고 깨어남 비용이 상품이다.', '체결 스레드가 큐가 비어 있을 때 park(대기)하지 않고 spin 하는 이유는?', array['코드를 짧게 하려고', '깨어나는 시스템콜/스케줄 비용이 꼬리 지연이 되니까', 'CPU를 식히려고', 'GC를 끄려고'], 1, 'park는 빠르지만 깨어남이 느릴 수 있다. 장이 바쁠 때는 코어를 잡고 도는 편이 꼬리가 짧다. 대신 CPU를 태운다.', 2),
  ('ib_eng_latency', 'ib_eng/clock-source', '시각을 찍는 시계와 간격을 재는 시계는 다르다.', '구간 지연을 wall clock(NTP)로만 재면 안 되는 이유는?', array['초 단위만 나와서', '시간이 뒤로 가거나 점프하면 구간이 음수·거대해진다', 'FIX에 시각 태그가 없어서', '평균만 계산되어서'], 1, '측정에는 단조 시계(TSC 등)가 맞다. 벽시계는 사람이 읽는 이벤트 시간에 쓴다. 둘을 섞으면 벤치마크가 거짓말한다.', 2),
  ('ib_eng_latency', 'ib_eng/syscall-log', '기록과 결정 경로를 같은 대기열에 넣지 않는다.', '핫패스에서 매 체결마다 동기 로그를 디스크에 쓰면?', array['감사에 더 안전하고 항상 더 빠르다', '시스템콜과 I/O가 꼬리 지연을 만든다', 'GC가 없어진다', '시퀀스 갭이 메워진다'], 1, '감사는 필요하지만 동기 fsync를 핫패스에 두면 장이 디스크를 기다린다. 저널은 비동기/배치하고, 재생 가능한 쓰기를 분리한다.', 2),
  ('ib_eng_latency', 'ib_eng/kernel-bypass-why', '느린 층이 어디인지 먼저 가리킨다.', '커널 바이패스 NIC를 쓰는 주된 이유는?', array['자바를 안 쓰려고', '패킷이 커널 소켓 스택을 건너뛰어 복사와 인터럽트를 줄이려고', 'FIX 세션을 없애려고', '회계 전표를 만들려고'], 1, '일반 소켓은 커널 복사·인터럽트·스케줄이 붙는다. 바이패스는 유저 공간에서 패킷을 본다. 애플리케이션 버그를 없애 주지는 않는다.', 2),
  ('ib_eng_latency', 'ib_eng/huge-pages', '주소 변환도 핫패스 비용이다.', '큰 페이지(huge pages)를 쓰는 이점은?', array['GC를 끈다', 'TLB 미스를 줄여 큰 버퍼/장부의 주소 변환 비용을 낮춘다', '네트워크 대역폭을 두 배로 만든다', 'SQL 격리를 높인다'], 1, '페이지가 크면 같은 메모리를 더 적은 TLB 항목으로 덮는다. 지연의 전부는 아니고, 큰 링 버퍼·오프힙에 의미가 있다.', 2),
  ('ib_eng_latency', 'ib_eng/batch-syscall', '싼 경로를 여러 번 부르는 것도 비용이다.', '패킷을 하나씩 send하는 대신 배치하는 이유는?', array['메시지 순서를 뒤집으려고', '시스템콜 당 오버헤드를 여러 메시지에 나눠 평균을 낮추려고', 'ExecID를 재사용하려고', 'IOC를 FOK로 바꾸려고'], 1, '콜 하나가 비싸다. 배치는 평균을 낮추지만 첫 메시지를 기다리게 할 수 있다. 꼬리와 평균의 트레이드오프다.', 2),
  ('ib_eng_latency', 'ib_eng/mechanical-sympathy', '추상화가 가리는 층이 지연을 만든다.', 'mechanical sympathy가 가리키는 것은?', array['UI를 엑셀처럼 만드는 것', '코드가 CPU 캐시·브랜치·NUMA의 실제 동작에 맞게 짜여 있는 것', '모든 것을 재귀로 짜는 것', 'SQL만으로 거래를 하는 것'], 1, '하드웨어가 잘하는 쪽으로 데이터 배치와 접근을 맞춘다. 디자인 패턴 이름이 아니라 측정 가능한 배치 이야기다.', 1),
  ('ib_eng_latency', 'ib_eng/exception-hot', '에러 경로는 빠른 경로가 아니다.', '핫패스에서 예외를 제어 흐름으로 쓰면?', array['JIT가 항상 더 빠르게 만든다', '스택 추적·분기 예측 실패로 지연이 뛰고, 정상 경로가 아니다', 'GC가 없어진다', 'FIX 시퀀스가 보정된다'], 1, '예외는 드물 때 쓰는 길이다. 매 틱마다 throw하면 프로파일에 보이지 않던 비용이 장이 열릴 때 나타난다.', 2),
  ('ib_eng_latency', 'ib_eng/lmax-ring', '미리 깔아 둔 배열과 락 대기를 비교한다.', '단일 작성자 링 버퍼가 큐+락보다 핫패스에서 유리한 이유는?', array['용량이 무한이라서', '캐시에 붙는 순차 쓰기와 락 없는 진행이 꼬리를 줄인다', 'GC가 객체를 안 만들어서', '네트워크를 안 써서'], 1, '미리 할당한 링은 인덱스를 밀며 쓴다. 락을 잡는 큐는 대기와 캐시 무효가 붙는다. 용량은 유한하다. 넘치면 백프레셔다.', 2),
  ('ib_eng_latency', 'ib_eng/context-switch', '스레드가 다시 달리기 전에 잃어버리는 것이 있다.', '컨텍스트 스위치가 저지연 경로에서 싫은 이유는?', array['스레드 이름이 바뀌어서', '캐시·TLB가 식고 커널이 끼어 꼬리가 길어진다', 'ExecID가 중복되어서', '시세 시퀀스가 리셋되어서'], 1, '코어를 잃으면 핫 데이터가 캐시에서 떨어진다. 코어 고정과 바쁜 루프는 그걸 피하려는 것이다.', 1),
  ('ib_eng_latency', 'ib_eng/p99-sla', '느린 한 건의 비율을 직접 읽는다.', '평균 80μs, p99 8ms인 게이트를 평균만 SLA로 걸면?', array['100건 중 1건이 장중 의미 있는 시간에 늦는 것을 허용한다', '모든 건이 80μs다', 'p99가 평균보다 항상 작다', 'GC가 없음을 증명한다'], 0, 'p99는 100건 중 느린 쪽이다. 8ms면 여러 호가가 지나간다. 평균 SLA는 그 1건을 숨긴다.', 3),
  ('ib_eng_latency', 'ib_eng/alloc-elide', '깨끗한 코드가 더러운 할당을 숨긴다.', '핫패스에서 문자열을 붙여 로그 키를 만들면 안 되는 이유는?', array['문자열이 더 정확해서', '숨은 할당과 인코딩이 GC·캐시를 건드린다', 'FIX 태그와 충돌해서', 'SQL 격리가 낮아져서'], 1, '보이는 new가 없어도 포맷터와 인코더가 할당한다. 식별자는 숫자/미리 intern한 심볼로 둔다.', 2),
  ('ib_eng_concurrency', 'ib_eng/happens-before', '보인다는 것은 언어 규칙이지 희망이 아니다.', '한 스레드가 쓴 포지션이 다른 스레드에 반드시 보이게 하려면?', array['필드를 public으로 둔다', 'happens-before를 만드는 동기화(락, volatile 기록/읽기, 안전한 발행)가 필요하다', '이름을 position으로 한다', 'GC를 끈다'], 1, 'JMM은 가시성을 자동으로 주지 않는다. public은 접근만 연다. 락의 해제-획득, volatile, 안전한 생성자 발행이 happens-before다.', 2),
  ('ib_eng_concurrency', 'ib_eng/volatile-not-enough', '보이는 것과 같이 맞는 것은 다르다.', 'volatile long size와 volatile long notional이 있을 때 size++와 notional+=px*qty를 각각 하면?', array['두 값이 항상 같이 맞는 스냅샷이다', '각 필드는 보여도 둘의 짝은 깨질 수 있다', '컴파일이 거절한다', '항상 원자적 쌍이다'], 1, 'volatile은 그 필드 하나의 가시성/원자성이다. 두 필드를 한 불변식으로 묶으려면 한 락이나 한 레코드 스왑이 필요하다.', 2),
  ('ib_eng_concurrency', 'ib_eng/cas-aba', '같아 보이는 포인터가 같은 생명이 아니다.', 'CAS로 호가 헤드를 바꾸는데 ABA가 위험한 이유는?', array['CAS가 항상 실패해서', '값이 A→B→A로 돌아와도 CAS는 성공해, 이미 빠진 노드를 다시 잇는다', 'GC가 ABA를 막아서', 'volatile이면 ABA가 없어서'], 1, '주소나 값이 같아 보여도 중간이 바뀌었다. 버전 스탬프나 위험하지 않은 구조가 필요하다. volatile은 ABA를 없애지 않는다.', 3),
  ('ib_eng_concurrency', 'ib_eng/single-writer', '공유를 줄이는 쪽이 잠금을 잘 쓰는 쪽보다 단순하다.', '단일 작성자(single-writer) 장부가 락보다 자주 쓰이는 이유는?', array['스레드를 하나만 켜면 법이 요구해서', '쓰는 손을 하나로 고정해 잠금 대기와 가시성 싸움을 없앤다', 'GC가 필요 없어서', 'FIX가 한 세션만 허용해서'], 1, '읽기는 여러 개여도 쓰기를 한 스레드에 모으면 불변식을 지키기 쉽다. 입구는 큐다. 스레드 수 규정이 아니다.', 1),
  ('ib_eng_concurrency', 'ib_eng/deadlock-vs-livelock', '멈춘 것과 바쁜데 못 나가는 것.', '데드락과 라이브락의 차이는?', array['데드락은 CPU를 태우고, 라이브락은 잔다', '데드락은 서로 기다려 진행이 0, 라이브락은 일은 하나 진행이 없다', '둘은 같은 말이다', '라이브락만 발생한다'], 1, '데드락은 사이클 대기. 라이브락은 양보만 반복한다. 둘 다 체결이 안 나간다. CPU 사용량만으로 구분하지 않는다.', 2),
  ('ib_eng_concurrency', 'ib_eng/sync-vs-volatile', '한 덩어리로 보여야 하는 갱신인지 묻는다.', '복합 갱신(포지션과 현금)을 한 덩어리로 보이게 하려면?', array['두 필드만 volatile', '같은 모니터/락으로 둘을 묶거나 한 불변 스냅샷을 발행', '둘 다 public', 'Thread.sleep(1)'], 1, '락은 임계구역의 원자성과 가시성을 같이 준다. volatile 두 개는 두 번의 보이는 쓰기다. sleep은 동기화가 아니다.', 2),
  ('ib_eng_concurrency', 'ib_eng/publication', '새 객체를 보여주는 것도 동기화다.', '객체를 생성한 뒤 다른 스레드에 넘길 때 안전한 발행이 아니면?', array['다른 스레드가 반쯤 초기화된 필드를 본다', '항상 컴파일 오류', 'GC가 객체를 지운다', 'FIX 시퀀스가 리셋된다'], 0, '생성자 끝과 참조 저장 사이에 happens-before가 없으면 기본값이 보인다. final 필드와 안전한 발행 관례가 그 구멍이다.', 2),
  ('ib_eng_concurrency', 'ib_eng/immutable-msg', '전달 뒤에 누가 고칠 수 있는지가 버그다.', '큐에 넣는 체결 이벤트를 불변으로 두는 이유는?', array['메모리를 더 쓰려고', '보낸 뒤 생산자가 필드를 바꿔도 소비자가 다른 값을 보지 않게', 'JSON이 필요해서', 'SQL이 못 읽어서'], 1, '가변 메시지를 재쓰면 큐 너머의 스레드가 경주를 한다. 불변이면 발행 후 이야기가 끝난다.', 1),
  ('ib_eng_concurrency', 'ib_eng/bounded-queue', '받지 못하는 상태를 숨기지 않는다.', '거래 입력 큐를 무한으로 두면?', array['절대 손실이 없다', '느린 소비자가 메모리를 키워 지연과 OOM이 장을 죽인다', 'GC가 빨라진다', '시세 갭이 메워진다'], 1, '유한 큐는 백프레셔다. 막는 쪽이 명시적이다. 무한 큐는 실패를 늦게, 더 크게 만든다.', 2),
  ('ib_eng_concurrency', 'ib_eng/yield-vs-spin', '양보도 비용이다.', '짧은 대기에서 Thread.sleep(0)/yield만 반복하면?', array['항상 spin보다 꼬리가 짧다', '스케줄러에 맡기므로 깨어남이 늦을 수 있다', 'CAS가 필요 없어진다', 'ABA가 사라진다'], 1, '양보는 다른 스레드에게 코어를 준다. 핫 스레드가 다시 붙는 시간이 꼬리다. 짧은 대기는 spin이 나을 수 있다.', 2),
  ('ib_eng_concurrency', 'ib_eng/rw-lock', '락의 종류를 고르기 전에 작성자 수를 센다.', '호가창 읽기가 많고 쓰기가 한 스레드일 때 RW 락보다 나은 경우가 많은 이유는?', array['읽기 락도 캐시 라인을 더럽히고, 단일 작성자+스냅샷이 더 단순하다', 'RW 락은 불법이다', '읽기는 항상 락이 필요하다', '쓰기가 락을 안 잡아서'], 0, '읽기 락 획득도 공유 카운터를 건드린다. 작성자가 버전/스냅샷을 발행하면 읽기는 락 없이 따라간다.', 2),
  ('ib_eng_concurrency', 'ib_eng/interrupt', '멈추라는 신호를 누가 먹는지 본다.', '대기 중인 스레드가 InterruptedException을 삼키고 계속 기다리면?', array['종료·취소 신호가 사라져 장중에도 못 죽는다', '항상 더 안전하다', 'GC가 정리한다', 'FIX가 재접속한다'], 0, '인터럽트는 협력적 정지다. 삼키면 kill switch나 셧다운이 그 스레드를 못 건드린다.', 1),
  ('ib_eng_concurrency', 'ib_eng/disruptor-role', '큐의 구현이지 시장의 규칙이 아니다.', 'LMAX Disruptor가 거래 경로에서 맡는 역할로 가장 가까운 것은?', array['SQL 엔진', '단일 작성자 링으로 이벤트를 락 없이 전달', 'FIX 세션 암호화', '엑셀 리본'], 1, '사전 할당된 링과 시퀀스로 생산자-소비자를 잇는다. DB도 아니고 UI도 아니다.', 2),
  ('ib_eng_concurrency', 'ib_eng/data-race-vs-race', '메모리 모델 위반과 업무 순서 위반을 나눈다.', '데이터 레이스와 일반적인 경쟁 조건의 차이는?', array['같다', '데이터 레이스는 동기화 없이 공유 메모리를 경합하는 것이고, 논리 경쟁은 락이 있어도 순서가 틀린 것이다', '데이터 레이스만 분산 시스템에서 난다', '경쟁 조건은 컴파일러만의 문제다'], 1, '데이터 레이스는 JMM이 UB에 가깝게 취급한다. 락을 잡아도 비즈니스 순서가 틀리면 그게 경쟁 조건이다. 둘 다 버그다.', 3),
  ('ib_eng_concurrency', 'ib_eng/lock-order', '두 자물쇠를 여는 순서가 순환이면 멈춘다.', '주문 락과 포지션 락을 두 코드 경로가 반대 순서로 잡으면?', array['더 빠르다', '데드락 사이클이 생긴다', '가시성이 자동으로 좋아진다', 'ABA만 생긴다'], 1, '락 순서를 전역으로 고정한다. 성능 최적화가 아니다. ABA는 CAS 이야기다.', 2),
  ('ib_eng_data', 'ib_eng/exec-unique', '한 번만 세야 하는 키를 고른다.', '체결 테이블에서 같은 드롭카피 재전송을 거절하는 최소 제약은?', array['symbol에 index', 'ExecID unique', 'ClOrdID unique', 'inserted_at unique'], 1, '재전송은 같은 ExecID를 다시 보낸다. ClOrdID unique면 부분 체결 두 번째가 거절된다. 시각 unique는 의미 없다.', 1),
  ('ib_eng_data', 'ib_eng/position-sum', '포지션은 사건의 합이다.', '포지션 수량으로 맞는 정의는?', array['마지막 체결 가격', '부호 있는 체결 수량의 합', '당일 주문 건수', '호가 잔량 합'], 1, '매수는 +, 매도는 −. 덮어쓴 현재값만 있으면 대사가 안 된다. 가격은 평가이지 수량 포지션이 아니다.', 1),
  ('ib_eng_data', 'ib_eng/lost-update', '읽은 값에 더해 쓰는 것은 경주다.', '두 세션이 같은 포지션 행을 읽고 각자 +10을 쓰면?', array['항상 20이 된다', '격리/원자 갱신이 없으면 한쪽 +10만 남을 수 있다', 'DB가 거절한다', 'ExecID가 바뀐다'], 1, '읽기-수정-쓰기는 lost update의 고전이다. UPDATE … SET qty = qty + 10 또는 이벤트만 insert 한다.', 2),
  ('ib_eng_data', 'ib_eng/rc-vs-serializable', '더티가 아니라고 한 순간의 합이 안정인 것은 아니다.', '리스크가 장중 포지션을 READ COMMITTED로 읽으면?', array['항상 하루 끝 스냅샷이다', '커밋된 행만 보지만 아직 안 끝난 주문의 중간 합과 레이스가 난다', '커밋 안 된 더티만 본다', '쓰기 락을 건다'], 1, 'RC는 더티를 안 본다. 그래도 두 번째 읽기 사이에 다른 체결이 커밋되면 합이 흔들린다. 스냅샷/직렬화가 다른 약속이다.', 2),
  ('ib_eng_data', 'ib_eng/vwap-window', '가중치는 가격이 아니라 수량이다.', '30분 VWAP을 SQL로 올바르게 고른 것은?', array['AVG(price)', 'SUM(price * qty) / NULLIF(SUM(qty), 0) over the window', 'MAX(price) - MIN(price)', 'COUNT(*) of trades'], 1, 'VWAP은 금액 합 / 수량 합이다. 단순 평균 가격은 작은 체결에 휘둘린다. 0 수량 나눗셈을 막는다.', 2),
  ('ib_eng_data', 'ib_eng/as-of-eod', '자르는 선이 흔들리면 날이 흔들린다.', 'EOD 포지션 as-of 18:00을 다음날 재계산하는데 시계가 서버마다 다르면?', array['항상 같은 숫자', '경계 체결이 어느 날에 들어갈지 서버마다 갈린다', 'ExecID가 바뀐다', 'FIX 35가 바뀐다'], 1, 'as-of는 한 시계에 대한 절단이다. 이벤트 시간을 거래소/합의 시계로 고정하고, 서버 로컬 now()를 쓰지 않는다.', 2),
  ('ib_eng_data', 'ib_eng/event-log', '결과만 남기고 원인을 버리면 운영이 죽는다.', '포지션을 행 하나로 덮어쓰고 이벤트 로그가 없으면?', array['더 정확하다', '대사·재생·감사가 불가능하고 누가 틀렸는지 재구성할 수 없다', 'GC가 빨라진다', 'IOC가 된다'], 1, '현재값은 캐시다. 소스 오브 트루스는 체결 사건이다. 덮어쓰기만 하면 어제 숫자와 오늘 숫자의 다리가 없다.', 2),
  ('ib_eng_data', 'ib_eng/null-vs-zero', '빈 칸이 0이 아니다.', '현금 잔고 NULL과 0을 같이 쓰면?', array['SQL에서 같다', '합계에서 NULL이 빠져 포지션이 있는 계정이 사라질 수 있다', 'unique가 깨진다', '항상 안전하다'], 1, 'SUM은 NULL을 건너뛴다. 없는 것과 0은 의미가 다르다. 잔고는 0으로 정규화하거나 없음을 따로 표시한다.', 2),
  ('ib_eng_data', 'ib_eng/reconcile-break', '합보다 집합을 먼저 본다.', '우리 체결 합과 브로커 확인 합이 다르면 먼저 할 일은?', array['우리 숫자를 브로커에 덮어쓴다', 'ExecID 집합 차집합으로 빠진/중복 체결을 찾는다', 'GC를 재시작한다', '모든 주문을 IOC로 바꾼다'], 1, '대사는 키 단위 차이다. 합만 맞추면 다른 두 오류가 상쇄된다. 덮어쓰기는 증거를 지운다.', 1),
  ('ib_eng_data', 'ib_eng/order-fill-tables', '1:N과 사건/상태를 나눈다.', '주문 테이블과 체결 테이블을 나누는 이유는?', array['정규화가 유행이라서', '한 주문에 체결이 여러 개이고 수명이 다르기 때문에', 'FIX가 테이블을 두 개 요구해서', '엑셀이 두 탭이라서'], 1, '주문은 상태 기계, 체결은 사건이다. 한 행에 최신 체결만 두면 부분을 잃는다.', 1),
  ('ib_eng_data', 'ib_eng/repeatable-read', '두 번째 읽기가 다른 세상을 볼 수 있는지 본다.', '같은 트랜잭션에서 포지션 합을 두 번 읽었더니 숫자가 바뀌었다. 가능한 격리는?', array['SERIALIZABLE만', 'READ COMMITTED (팬텀/논반복)', '테이블 락을 건 스냅샷', '실행이 불가능하다'], 1, 'RC는 매 문장이 새 스냅샷에 가깝다. 반복 읽기를 약속하지 않는다. 직렬화/스냅샷은 그 약속을 더 강하게 한다.', 3),
  ('ib_eng_data', 'ib_eng/window-running', '접지 않고 행마다 누적을 붙인다.', '심볼별 당일 누적 수량을 창함수로 쓰려면?', array['SUM(qty) OVER (PARTITION BY symbol ORDER BY ts)', 'AVG(qty) GROUP BY account', 'DISTINCT exec_id', 'MAX(price) OVER ()'], 0, '파티션은 심볼, 순서는 시간. GROUP BY만 쓰면 행이 접혀 체결 단위가 사라진다.', 2),
  ('ib_eng_data', 'ib_eng/idempotent-upsert', '다시 넣어도 합이 같아야 한다.', '체결 upsert를 (exec_id) 충돌 시 do nothing으로 두는 이유는?', array['가격을 최신으로 덮으려고', '재처리가 수량을 두 번 더하지 않게', 'ClOrdID를 바꾸려고', '시세를 맞추려고'], 1, '멱등 소비는 같은 키를 무시한다. 충돌 시 가격을 덮으면 첫 체결의 증거가 바뀐다.', 2),
  ('ib_eng_data', 'ib_eng/soft-delete', '없었던 일로 만들면 네트워크가 다시 가져온다.', '잘못된 체결을 DELETE로 지워 버리면?', array['대사가 더 쉽다', '감사와 재생이 구멍을 모르고, 드롭카피 재전송이 유령으로 돌아온다', 'unique가 좋아진다', '항상 맞다'], 1, '취소/정정은 반대 사건이나 무효 표시로 남긴다. 물리적 삭제는 키가 다시 비어 재삽입된다.', 2),
  ('ib_eng_data', 'ib_eng/clock-txn', '언제 일어났는지와 언제 받았는지는 다르다.', '트랜잭션 타임스탬프를 now()로 찍고, 이벤트 시간을 거래소 sending time으로 안 두면?', array['항상 같다', '지연된 메시지가 우리 시계 기준으로 늦게 들어와 창·EOD가 틀린다', 'ExecID가 충돌한다', '격리 수준이 올라간다'], 1, '처리 시간과 사건 시간을 분리한다. 창함수와 as-of는 사건 시간을 쓴다.', 3),
  ('ib_eng_systems', 'ib_eng/kill-switch', '더 이상 쏘지 않는 것이 첫 계약이다.', 'kill switch가 켜졌을 때 최소한 보장해야 하는 것은?', array['이미 나간 모든 주문을 더 빨리 체결', '신규 주문이 시장으로 나가지 않음', '시세 피드를 끈다', 'DB를 drop한다'], 1, '스위치의 1번은 추가 주문을 막는 것이다. 기존 주문을 취소할지는 별 규칙이다. 시세를 끄는 것과 같지 않다.', 1),
  ('ib_eng_systems', 'ib_eng/at-least-once', '한 번 보내기와 한 번 적용은 다른 층이다.', '네트워크가 at-least-once일 때 exactly-once 체결을 만드는 방법은?', array['TCP를 두 번 연다', '수신 측이 ExecID(또는 시퀀스)로 멱등 적용한다', 'UDP만 쓴다', '평균 지연을 낮춘다'], 1, '전송이 한 번만이라고 믿을 수 없다. 한 번만 적용하는 것은 소비자다. 소켓 종류가 해결하지 않는다.', 2),
  ('ib_eng_systems', 'ib_eng/journal-replay', '죽어도 같은 순서의 사건이 남는지 본다.', '프로세스가 죽은 뒤 포지션을 다시 맞추는 기본 수단은?', array['어제 EOD를 그대로 쓴다', '저널/이벤트 로그를 순서대로 재생한다', '호가 스냅샷만 읽는다', 'GC 로그를 읽는다'], 1, '재생 가능한 쓰기가 소스다. EOD는 출발점일 수 있지만 장중 사건을 빠뜨린다. 호가는 포지션이 아니다.', 2),
  ('ib_eng_systems', 'ib_eng/dual-write', '두 번의 성공은 한 번의 성공이 아니다.', '주문 insert와 체결 insert를 다른 커밋으로 나누면?', array['항상 더 안전하다', '한쪽만 커밋되어 장부가 어긋날 수 있다', 'unique가 필요 없어진다', 'kill switch가 자동이다'], 1, '이중 쓰기는 원자성이 없다. 한 트랜잭션, outbox, 또는 단일 이벤트 스트림으로 묶는다.', 3),
  ('ib_eng_systems', 'ib_eng/backpressure', '못 소화하는 입력을 쌓아 두지 않는다.', '매칭이 느린데 게이트가 주문을 계속 받으면?', array['처리량이 무한이다', '큐가 커져 지연이 폭발하고 결국 메모리/세션이 죽는다', 'p99가 항상 내려간다', '대사가 자동이다'], 1, '백프레셔는 입구를 늦추거나 거절한다. 무한 수락은 실패를 미룬다.', 2),
  ('ib_eng_systems', 'ib_eng/poison', '한 불량 이벤트가 장을 세우면 안 된다.', '한 메시지가 파싱에 실패해 큐를 막으면?', array['프로세스를 영구히 재시도하며 전체를 멈춘다', '독 메시지를 격리하고 시퀀스의 나머지는 진행한다', 'DB를 지운다', '모든 세션을 Logon부터 한다'], 1, '독 메시지는 건너뛰고 경보한다. 전체를 그 한 건에 묶으면 kill이 안 된다. 무한 재시도가 답이 아니다.', 2),
  ('ib_eng_systems', 'ib_eng/pre-vs-post-risk', '막기와 발견은 시각이 다르다.', '프리트레이드 리스크와 포스트트레이드 리스크의 차이는?', array['프리만 있으면 된다', '프리는 전송 전 거절, 포스트는 체결 후 한도/이상 탐지', '포스트가 전송을 막는다', '둘 다 시세만 본다'], 1, '나간 주문은 프리로 못 되돌린다. 포스트는 깨진 것을 찾고 스위치를 당긴다. 한 쪽만 있으면 구멍이 난다.', 2),
  ('ib_eng_systems', 'ib_eng/limit-race', '남은 한도는 공유 자원이다.', '한도 잔여를 읽고 주문을 보내는 사이에 다른 주문이 나가면?', array['한도가 항상 맞다', '두 주문이 한도를 같이 뚫을 수 있다', 'FIX가 막는다', 'GC가 막는다'], 1, '예약은 원자적이어야 한다. 읽기-전송은 경주다. 단일 작성자나 원자 차감이 그 구멍이다.', 3),
  ('ib_eng_systems', 'ib_eng/warm-standby', '살아있는 펜을 몇 개 둘지다.', 'warm standby가 active-active보다 단순한 이유는?', array['처리량이 항상 두 배라서', '한 쪽만 쓰고 다른 쪽은 재생만 해 이중 체결을 피한다', '네트워크가 필요 없어서', '대사가 필요 없어서'], 1, '액티브-액티브는 두 쓰기가 같은 주문을 시장에 낼 수 있다. 스탠바이는 승격 전까지 침묵한다. 처리량은 희생이다.', 2),
  ('ib_eng_systems', 'ib_eng/seq-gap-app', '없는 번호는 없는 사건이 아니다.', '애플리케이션 시퀀스가 비면?', array['다음 주문을 두 번 낸다', '갭을 메우기 전에 그 구간의 상태를 확정하지 않는다', '시세를 0으로 둔다', '한도를 두 배로 한다'], 1, '세션 층 재전송과 같다. 빈 번호의 체결을 없다고 치면 포지션이 빠진다.', 2),
  ('ib_eng_systems', 'ib_eng/reconcile-sot', '빠른 복사본과 합의된 장부를 섞지 않는다.', '게이트 메모리 포지션과 거래소 드롭카피가 다르면 소스는?', array['게이트 메모리', '합의된 외부 장부(드롭카피/확인)와 그 차이의 티켓', 'p99 로그', '엑셀 시트'], 1, '로컬 캐시는 빨리 죽거나 다시 시작된다. 운영의 진실은 대사 결과다. 메모리를 맞다고 우기면 다음날도 틀린다.', 2),
  ('ib_eng_systems', 'ib_eng/outbox', '저장과 전송을 한 기록으로 만든다.', 'DB 커밋과 FIX 전송을 묶는 outbox 패턴이 푸는 문제는?', array['GC 일시정지', '커밋은 됐는데 전송이 안 되거나 그 반대인 이중 쓰기', '시세 갭', '엑셀 순환참조'], 1, '같은 저장소에 ‘보낼 메시지’를 커밋하고 전송기는 그 테이블을 본다. 두 인프라에 따로 쓰는 구멍을 줄인다.', 2),
  ('ib_eng_systems', 'ib_eng/idempotent-gateway', '클라이언트 재시도가 기본값이다.', '클라이언트가 같은 ClOrdID로 새 주문을 두 번 POST하면 게이트는?', array['두 주문을 시장에 낸다', '같은 주문으로 보고 두 번째를 거절/재응답한다', 'ExecID를 재사용한다', '한도를 무시한다'], 1, '재시도는 정상이다. ClOrdID가 멱등 키다. 두 번째를 새 주문으로 내면 두 배가 나간다.', 1),
  ('ib_eng_systems', 'ib_eng/standby-split', '침묵이 죽음인지 가림인지 구분한다.', '스탠바이가 하트비트를 잃고 둘 다 액티브가 되면?', array['처리량만 좋아진다', '같은 주문이 두 번 시장에 나갈 수 있다', '대사가 자동으로 맞는다', '시세가 더 정확해진다'], 1, '스플릿 브레인이다. 펜스는 스토리지/시퀀스 소유권으로 한 쪽만 쓰게 한다. 하트비트만 믿으면 안 된다.', 3),
  ('ib_eng_systems', 'ib_eng/cancel-on-disconnect', '손 놓은 주문이 살아 있으면 위험하다.', '세션이 끊길 때 미체결을 거래소가 취소하는 규칙(cancel on disconnect)이 있는 이유는?', array['시세를 아끼려고', '죽은 게이트가 장을 계속 찌르지 않게', '포지션을 두 배로 하려고', 'GC를 도우려면'], 1, '연결이 없으면 우리가 관리할 수 없다. 잔량이 남아 있으면 통제 불가다. 모든 시장이 이 규칙을 주지 않는다 — 있으면 계약이다.', 2),
  ('ib_eng_ds', 'ib_eng/book-sides', '각 쪽의 ‘앞’이 베스트다.', '호가창에서 매수와 매도의 정렬은?', array['둘 다 가격 오름차순', '매수는 높은 가격이 앞, 매도는 낮은 가격이 앞', '둘 다 수량 내림차순', '들어온 시간만'], 1, '베스트 비드가 가장 높은 매수, 베스트 애스크가 가장 낮은 매도다. 시간만으로 가격을 이기지 않는다.', 1),
  ('ib_eng_ds', 'ib_eng/level-fifo', '가격이 같으면 줄이다.', '같은 가격 레벨 안에서 수량을 빼는 순서는 보통?', array['큰 수량부터', '먼저 들어온 잔량부터 (FIFO)', '무작위', '고객 계정 번호 순'], 1, 'price-time의 time은 레벨 안 큐다. 프로 라타는 다른 매칭 규칙이다. 크기가 우선이 아니다.', 2),
  ('ib_eng_ds', 'ib_eng/book-structure', '두 층이다: 가격과 시간.', '호가창 구현으로 흔한 조합은?', array['가격 레벨은 트리/맵, 레벨 안은 큐', '모든 주문을 배열에 넣고 매번 정렬', '한 개의 스택', 'SQL만'], 0, '레벨 찾기/베스트는 정렬된 맵이 잘 맞고, 레벨 안 체결은 큐다. 매번 전체 정렬은 장이 못 기다린다.', 2),
  ('ib_eng_ds', 'ib_eng/vwap-def', '무엇을 가중하는지 말한다.', '구간 VWAP의 정의는?', array['첫 가격과 끝 가격의 평균', 'Σ(price×qty) / Σ(qty)', '최고가', '체결 건수의 평균 가격'], 1, '수량 가중이다. 1주 체결과 100만주 체결을 같은 표로 보면 안 된다.', 1),
  ('ib_eng_ds', 'ib_eng/two-heaps-median', '중간을 두 우선순위 큐의 경계에 둔다.', '스트리밍 체결 가격의 중앙값을 O(log n)에 유지하는 구조는?', array['한 개의 스택', '낮은 절반 max-heap + 높은 절반 min-heap', '해시셋만', '원형 버퍼만'], 1, '두 힙의 뿌리가 중앙(또는 짝수면 두 뿌리)이다. 스택은 순서가 다르고, 셋은 순서를 안 준다.', 2),
  ('ib_eng_ds', 'ib_eng/sliding-vol', '들어오는 것과 나가는 것만 고친다.', '최근 60초 거래량을 틱마다 갱신하려면?', array['매일 처음부터 SUM', '만료 시각 순 deque + 누적 합', 'BST에서 심볼만 찾기', '재귀 DFS'], 1, '창에서 빠지는 체결을 앞에서 빼고 새 체결을 뒤에 넣는다. 전체 재합은 O(n)이다.', 2),
  ('ib_eng_ds', 'ib_eng/exec-set', '본 적 있는지 O(1)에 묻는다.', '중복 체결을 메모리에서 거절하는 최소 구조는?', array['ExecID 해시셋', '가격 힙', '스택', '트라이로 심볼'], 0, '멤버십이다. 힙은 순서, 스택은 LIFO. 심볼 트라이는 중복 키가 아니다.', 1),
  ('ib_eng_ds', 'ib_eng/stop-pq', '다음에 터질 가격이 루트에 있어야 한다.', '스탑 주문을 트리거 가격 순으로 감시하는 구조는?', array['우선순위 큐(힙)', 'FIFO 큐만', '해시셋만', '이중 연결 리스트만'], 0, '시장이 그 가격에 닿는 순간 가장 가까운 스탑을 꺼내야 한다. FIFO는 시간이 가격을 이긴다.', 2),
  ('ib_eng_ds', 'ib_eng/prefix-pnl', '구간 합은 누적의 차이다.', '시간 순 체결에서 구간 실현손익을 O(1)에 보려면 미리 무엇을 쌓는가?', array['접두 합(prefix sum)', '그래프 최단경로', '트라이', '유니온 파인드'], 0, '누적 금액/수량의 차분이 구간이다. 최단경로와 집합 합치기는 다른 문제다.', 2),
  ('ib_eng_ds', 'ib_eng/bsearch-ts', '정렬되어 있으면 로그 시간에 자른다.', '정렬된 체결 시각 배열에서 14:00 이후 첫 체결을 찾는 방법은?', array['선형 스캔만 가능', '하한(lower bound) 이분 탐색', 'DFS', '다익스트라'], 1, '단조 시각이면 이분 탐색이다. 그래프 알고리즘이 아니다.', 2),
  ('ib_eng_ds', 'ib_eng/lru-session', '버리기의 대상을 고르는 정책이다.', '세션 캐시에 LRU를 쓰는 이유와 함정은?', array['가장 안 쓴 것을 버려 메모리를 묶지만, 장중 심볼이 쫓겨나면 재계산이 꼬리다', '항상 무제한 메모리가 생긴다', '순서 통계를 준다', 'VWAP을 계산한다'], 0, '용량 한도와 지역성의 타협이다. 핫 심볼이 캐시에서 떨어지면 지연이 튄다. 핀이 필요할 수 있다.', 2),
  ('ib_eng_ds', 'ib_eng/match-walk', '공격 주문은 반대 쪽 베스트부터다.', '시장가 매수가 들어왔을 때 매칭이 걷는 방향은?', array['매수 쪽 베스트부터', '매도 쪽 베스트(가장 낮은 ask)부터 가격을 올리며', '무작위 레벨', '가장 깊은 매도부터'], 1, '사는 주문은 싼 매도를 먹는다. 매수 북을 걸으면 같은 쪽과 싸운다.', 3),
  ('ib_eng_ds', 'ib_eng/spread', '두 베스트의 간격이다.', '스프레드의 정의는?', array['당일 최고가 − 최저가', '베스트 ask − 베스트 bid', 'VWAP − 종가', '미결제약정'], 1, '지금 사거나 파는 비용의 한 줄이다. 고저 범위는 다른 통계다.', 1),
  ('ib_eng_ds', 'ib_eng/time-priority-reprice', '가격을 고치면 시간을 다시 산다.', '지정가 매수가 가격을 올리면 시간 우선은?', array['원래 시간을 유지한다', '보통 새 가격의 새 시간으로 줄을 다시 선다', '수량이 크면 유지', '항상 맨 앞'], 1, '가격을 바꾸면 새 주문으로 보는 시장이 많다. 줄을 새치기하지 못한다. 규칙 문서를 확인하되 기본 직관은 재줄서기다.', 3),
  ('ib_eng_ds', 'ib_eng/not-twosum', '자료구조를 시장 이야기로 말한다.', 'IB 테크 면접에서 일반 two-sum 배열 문제보다 나은 출발은?', array['호가창에서 상대 쪽 가격을 찾는 이야기', '피보나치 재귀', '엑셀 SUMIFS', 'CSS 플렉스'], 0, '같은 이분/해시 아이디어를 장부 맥락에 두면 직무가 보인다. 일반 퍼즐은 직무와 끊긴다.', 1);
